"""SCALE = 0.27

def save(name_, y, peak=27000, path='/workspace/snd'):
    y = np.asarray(y, dtype=np.float64)
    if y.size == 0: raise ValueError("empty sample " + name_)
    m = np.abs(y).max()
    if m > 0: y = y * (peak / m) * SCALE""")
open('sounds.py','w').write(src)
EOF
